import{_ as a,o,c as i,a2 as t}from"./chunks/framework.CgxQ0r6v.js";const p=JSON.parse('{"title":"Planificación Académica: Proyecto Sociotecnológico II (Trimestre V)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_II/Planificacion_Trimestre_II-V.md","filePath":"materias/Proyecto_Sociotecnologico_II/Planificacion_Trimestre_II-V.md"}'),d={name:"materias/Proyecto_Sociotecnologico_II/Planificacion_Trimestre_II-V.md"};function l(r,e,n,s,c,u){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="planificacion-academica-proyecto-sociotecnologico-ii-trimestre-v" tabindex="-1">Planificación Académica: Proyecto Sociotecnológico II (Trimestre V) <a class="header-anchor" href="#planificacion-academica-proyecto-sociotecnologico-ii-trimestre-v" aria-label="Permalink to &quot;Planificación Académica: Proyecto Sociotecnológico II (Trimestre V)&quot;">​</a></h1><p>En este trimestre se lleva a cabo el núcleo de ingeniería del software del proyecto: la selección y aplicación de la metodología de desarrollo, el modelado formal de procesos y datos mediante UML, y la codificación del prototipo funcional de la aplicación informática.</p><hr><h2 id="📅-trimestre-v-metodologia-modelado-del-sistema-y-construccion-del-prototipo-unidad-4-y-unidad-6" tabindex="-1">📅 Trimestre V: Metodología, Modelado del Sistema y Construcción del Prototipo (Unidad 4 y Unidad 6) <a class="header-anchor" href="#📅-trimestre-v-metodologia-modelado-del-sistema-y-construccion-del-prototipo-unidad-4-y-unidad-6" aria-label="Permalink to &quot;📅 Trimestre V: Metodología, Modelado del Sistema y Construcción del Prototipo (Unidad 4 y Unidad 6)&quot;">​</a></h2><h3 id="📝-evaluacion-1-metodologias-de-desarrollo-de-software-unidad-4" tabindex="-1">📝 Evaluación 1: Metodologías de Desarrollo de Software (Unidad 4) <a class="header-anchor" href="#📝-evaluacion-1-metodologias-de-desarrollo-de-software-unidad-4" aria-label="Permalink to &quot;📝 Evaluación 1: Metodologías de Desarrollo de Software (Unidad 4)&quot;">​</a></h3><p><strong>Objetivo:</strong> Comparar, seleccionar y justificar la metodología de ingeniería de software más apropiada para el contexto del proyecto y el alcance del PST II.</p><ul><li>Paradigmas de desarrollo: Metodologías Tradicionales (Cascada, RUP) vs. Metodologías Ágiles (Scrum, XP, Kanban).</li><li>Metodologías de Software Libre en la administración pública (MERINDE, WATCH).</li><li>Justificación de la metodología seleccionada en función del equipo, la comunidad y los tiempos de entrega.</li><li>Adaptación del ciclo de vida del proyecto a las fases o sprints metodológicos.</li><li><strong>Actividad:</strong> <strong>Cuadro Comparativo y Justificación Metodológica en Informe de Proyecto.</strong> (25%)</li></ul><h3 id="📝-evaluacion-2-analisis-y-modelado-orientado-a-objetos-con-uml-unidad-4" tabindex="-1">📝 Evaluación 2: Análisis y Modelado Orientado a Objetos con UML (Unidad 4) <a class="header-anchor" href="#📝-evaluacion-2-analisis-y-modelado-orientado-a-objetos-con-uml-unidad-4" aria-label="Permalink to &quot;📝 Evaluación 2: Análisis y Modelado Orientado a Objetos con UML (Unidad 4)&quot;">​</a></h3><p><strong>Objetivo:</strong> Diseñar los modelos conceptuales, de comportamiento y de estructura que guiarán la construcción del software.</p><ul><li>Lenguaje Unificado de Modelado (UML): fundamentos y tipos de diagramas.</li><li>Modelado funcional: Diagramas de Casos de Uso y Especificación Textual de Casos de Uso.</li><li>Modelado dinámico: Diagramas de Actividades y Diagramas de Secuencia.</li><li>Modelado estructural: Diagramas de Clases del dominio del problema.</li><li><strong>Actividad:</strong> <strong>Dossier de Modelado UML y Validación de Flujos.</strong> (25%)</li></ul><h3 id="📝-evaluacion-3-diseno-de-arquitectura-y-base-de-datos-unidad-4" tabindex="-1">📝 Evaluación 3: Diseño de Arquitectura y Base de Datos (Unidad 4) <a class="header-anchor" href="#📝-evaluacion-3-diseno-de-arquitectura-y-base-de-datos-unidad-4" aria-label="Permalink to &quot;📝 Evaluación 3: Diseño de Arquitectura y Base de Datos (Unidad 4)&quot;">​</a></h3><p><strong>Objetivo:</strong> Diseñar la persistencia de datos relacional y definir la arquitectura de software bajo estándares abiertos.</p><ul><li>Diseño de Base de Datos: Modelo Entidad-Relación (MER) y Modelo Relacional (MR).</li><li>Normalización de datos (1FN, 2FN, 3FN) e integridad referencial.</li><li>Diccionario de datos y scripts DDL en motores libres (PostgreSQL, MariaDB/MySQL o SQLite).</li><li>Definición de arquitectura de la aplicación: Patrón Modelo-Vista-Controlador (MVC), arquitecturas multicapas y diseño de interfaces de usuario (UI/UX).</li><li><strong>Actividad:</strong> <strong>Defensa del Modelo de Base de Datos y Prototipos de Pantallas (Wireframes).</strong> (25%)</li></ul><h3 id="📝-evaluacion-4-construccion-y-demostracion-del-prototipo-funcional-unidades-4-y-6" tabindex="-1">📝 Evaluación 4: Construcción y Demostración del Prototipo Funcional (Unidades 4 y 6) <a class="header-anchor" href="#📝-evaluacion-4-construccion-y-demostracion-del-prototipo-funcional-unidades-4-y-6" aria-label="Permalink to &quot;📝 Evaluación 4: Construcción y Demostración del Prototipo Funcional (Unidades 4 y 6)&quot;">​</a></h3><p><strong>Objetivo:</strong> Implementar los módulos esenciales del software y demostrar la funcionalidad del prototipo preliminar.</p><ul><li>Codificación en entornos y lenguajes abiertos (PHP, Python, JavaScript, Java, etc.).</li><li>Gestión de versiones colaborativa con Git y buenas prácticas de código limpio.</li><li>Integración del módulo de autenticación, control de roles y operaciones CRUD principales.</li><li>Demostración en vivo del prototipo funcional ante el comité evaluador y tutores.</li><li><strong>Actividad:</strong> <strong>2do Informe de Avance (Avance de Solución + Prototipo en Vivo).</strong> (25%)</li></ul><hr><h2 id="✅-resumen-del-trimestre" tabindex="-1">✅ Resumen del Trimestre <a class="header-anchor" href="#✅-resumen-del-trimestre" aria-label="Permalink to &quot;✅ Resumen del Trimestre&quot;">​</a></h2><p>Al finalizar el Trimestre V, el equipo contará con el 2do informe de avance aprobado, el diseño técnico detallado (UML y Base de Datos) y un prototipo funcional operativo que cubre los requerimientos nucleares de la comunidad, listo para someterse a pruebas rigurosas e implantación en el trimestre final.</p>',19)])])}const g=a(d,[["render",l]]);export{p as __pageData,g as default};
